export function clamp(value, low, high) {
  if (value < low) return low;
  if (value > high) return high;
  return value;
}

test("below low returns low", () => { assert.equal(clamp(-3, 0, 10), 0); });

test("above high returns high", () => { assert.equal(clamp(15, 0, 10), 10); });

test("inside range returns value", () => { assert.equal(clamp(5, 0, 10), 5); });

test("equal to low returns low", () => { assert.equal(clamp(0, 0, 10), 0); });

test("equal to high returns high", () => { assert.equal(clamp(10, 0, 10), 10); });
